-- FASE D · Bloque 4 · Juan y Hechos
update public.biblical_books
set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('coverage_status','context_ready'),updated_at=now()
where code in ('JHN','ACT');

with source as(select id from public.biblical_sources where slug='vida-contexto-editorial'),
data(slug,book_code,scope_kind,chapter_start,chapter_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places) as(values
('juan-perfil','JHN','book',1,21,'Juan: señales, identidad de Jesús y vida en Dios','Juan presenta a Jesús como la Palabra hecha carne, organiza su ministerio alrededor de señales y fiestas judías y desarrolla temas de vida, luz, testimonio, amor, gloria y permanencia.','El evangelio refleja el judaísmo del siglo I y probablemente debates comunitarios posteriores a la destrucción del templo. Su relación con tradiciones sinópticas, fecha y ubicación exactas son debatidas.','Las fiestas, el templo, Moisés, Abraham y las Escrituras de Israel estructuran el relato. La expresión «los judíos» suele referirse según contexto a autoridades o grupos específicos y no al pueblo judío entero.','Un prólogo poético abre un libro de señales y un libro de gloria. Diálogos con doble sentido, malentendidos, discursos y testimonios forman una teología narrativa propia.','Invitar a confiar en Jesús como revelador del Padre y recibir vida que se expresa en amor, verdad, servicio y permanencia.','La fe no es aceptación aislada de datos, sino relación y práctica. Ver la gloria de Dios implica contemplar una entrega que lava pies y da vida.','Juan no debe usarse para antisemitismo. Sus afirmaciones elevadas sobre Jesús son teológicas y no eliminan su humanidad judía. «Nacer de nuevo» también puede significar nacer de arriba y no debe reducirse a una fórmula verbal.',ARRAY['Logos','señales','vida','luz','testimonio','gloria','permanecer']::text[],ARRAY['judíos','discípulos','samaritanos','romanos','comunidad joánica']::text[],ARRAY['Galilea','Jerusalén','Samaria','Betania']::text[]),
('juan-1-4-testimonio-inicios','JHN','section',1,4,'Prólogo, testimonio y primeros encuentros','El prólogo presenta a la Palabra, Juan da testimonio, discípulos son llamados y las escenas de Caná, templo, Nicodemo y la mujer samaritana introducen señales, nuevo nacimiento, agua viva y adoración.','Caná y Galilea reflejan vida aldeana; Jerusalén y el templo concentran peregrinación y poder. La relación entre judíos y samaritanos estaba marcada por historia, santuarios rivales y conflicto.','La Palabra retoma creación, sabiduría y revelación. Nicodemo representa debate dentro de Israel; la conversación samaritana reconoce una tradición relacionada pero distinta.','El prólogo es seguido por una semana de testimonios y encuentros individuales que avanzan desde «ven y ve» hasta confesiones más amplias.','Presentar a Jesús como presencia reveladora que encuentra personas en contextos diversos y mueve de señales externas hacia comprensión relacional.','La transformación puede comenzar con curiosidad, preguntas o una conversación inesperada. Dios no queda limitado a una montaña, edificio o grupo.','La mujer samaritana no debe presentarse como inmoral sin evidencia explícita; su historia matrimonial admite distintas explicaciones sociales. Juan 2 no autoriza violencia religiosa. El «agua viva» es metáfora y no producto milagroso comercializable.',ARRAY['Palabra','Juan Bautista','Caná','Nicodemo','samaritana','agua viva','adoración']::text[],ARRAY['discípulos','judíos','samaritanos','familias']::text[],ARRAY['Caná','Jerusalén','Sicar','Samaria']::text[]),
('juan-5-12-senales-conflicto','JHN','section',5,12,'Señales, fiestas y creciente conflicto','Sanidades, alimentación, caminar sobre el mar, discursos de pan y luz, apertura de ojos y resurrección de Lázaro desarrollan identidad y misión mientras crece la oposición.','Las fiestas de Pascua, Tabernáculos y Dedicación daban marco litúrgico y nacional a los discursos. Las autoridades romanas y sacerdotales temían inestabilidad.','Jesús interpreta sábado, maná, agua, luz y pastor desde las Escrituras. Las discusiones reflejan conflictos judíos internos y quizá tensiones posteriores de la comunidad del evangelio.','Siete señales tradicionalmente identificadas avanzan hacia Lázaro, seguida por una decisión de matar a Jesús y una transición a su hora.','Mostrar que las señales apuntan más allá de asombro hacia vida, cuidado y revelación, y que la luz también expone intereses institucionales.','La fe puede crecer de manera progresiva, como en el hombre que recupera la vista. La vida recibida conduce a testimonio, pero no garantiza aprobación social.','Juan 6 no debe reducirse sin contexto a una sola doctrina sacramental. Juan 8:44 no autoriza llamar «hijos del diablo» a judíos ni a grupos rivales. Los relatos de sanidad no culpan a quien no sana.',ARRAY['sábado','pan de vida','Tabernáculos','luz','buen pastor','Lázaro','señales']::text[],ARRAY['discípulos','fariseos','autoridades','multitudes','familia de Betania']::text[],ARRAY['Jerusalén','Galilea','Betania']::text[]),
('juan-13-17-despedida','JHN','section',13,17,'Lavatorio, mandamiento del amor y discursos de despedida','Jesús lava los pies, anuncia traición y partida, promete al Paráclito, utiliza la imagen de la vid y ora por sus discípulos y por quienes creerán después.','El lavado de pies era tarea de hospitalidad de bajo estatus. Las comidas de despedida y relaciones maestro-discípulo daban peso a la inversión de roles.','El mandamiento nuevo se arraiga en el amor de Dios y en la Torá, pero adquiere forma concreta en el servicio de Jesús. El Paráclito es descrito con funciones de presencia, enseñanza y testimonio.','Cinco capítulos ralentizan el tiempo de la cena y alternan diálogo, metáfora y oración antes del arresto.','Definir liderazgo y comunidad mediante servicio, amor verificable, verdad y dependencia de la presencia divina.','Permanecer no significa inmovilidad, sino recibir vida y producir fruto de amor. La unidad orada no exige uniformidad ni encubrimiento de daño.','El lavatorio no debe usarse para humillar ni forzar intimidad. «Pidan lo que quieran» no es cheque en blanco separado de permanecer y propósito. La unidad no obliga a tolerar abuso o corrupción.',ARRAY['lavatorio','mandamiento nuevo','Paráclito','vid','permanecer','unidad','oración']::text[],ARRAY['discípulos','comunidad futura']::text[],ARRAY['Jerusalén']::text[]),
('juan-18-21-pasion-resurreccion','JHN','section',18,21,'Pasión, señales de resurrección y restauración de Pedro','Jesús es arrestado, interrogado por autoridades judías y romanas, crucificado, sepultado y visto resucitado por María y los discípulos; el epílogo restaura a Pedro y redefine su misión pastoral.','La crucifixión era ejecución romana. El evangelio presenta tensiones entre prefecto, sacerdocio y multitud dentro de un sistema imperial complejo.','La Pascua y el cordero influyen en la cronología y simbolismo propios de Juan. María Magdalena es primera testigo; Tomás pasa de ausencia y duda a confesión.','La pasión se narra como hora de glorificación y control narrativo, seguida por apariciones que responden a duelo, miedo, duda y fracaso.','Mostrar que el poder imperial y religioso no derrota la vida revelada en Jesús y que la misión nace de paz, Espíritu, testimonio y cuidado del rebaño.','La resurrección se encuentra con personas de maneras distintas: por nombre, en comunidad, mediante preguntas o en trabajo cotidiano. La restauración incluye responsabilidad y cuidado.','No debe culparse colectivamente al pueblo judío. La frase a Tomás no condena preguntas honestas. «Apacienta mis ovejas» no autoriza control pastoral ni convierte el liderazgo en posesión de personas.',ARRAY['Pilato','crucifixión','María Magdalena','Tomás','resurrección','Pedro','apacentar']::text[],ARRAY['discípulos','mujeres','autoridades sacerdotales','romanos']::text[],ARRAY['Jerusalén','Gólgota','tumba','Galilea']::text[]),
('hechos-perfil','ACT','book',1,28,'Hechos: Espíritu, testimonio y expansión hasta Roma','Hechos continúa el relato de Lucas y narra cómo el Espíritu forma una comunidad en Jerusalén, atraviesa Samaria, incorpora gentiles y lleva el testimonio de Jesús hasta Roma mediante conflictos, discernimiento y viajes.','El libro recorre Judea, Siria, Asia Menor, Grecia y Roma en el siglo I, bajo administración imperial y mediante redes de sinagogas, ciudades, caminos y navegación.','La primera comunidad permanece judía y participa en templo y Escrituras. La incorporación gentil genera debates reales sobre circuncisión, mesa y Torá, resueltos mediante discernimiento comunitario más que rechazo de Israel.','Hechos 1:8 ofrece el mapa narrativo: Jerusalén, Judea y Samaria, y hasta los confines. Discursos, resúmenes, viajes y juicios estructuran el avance.','Mostrar que la misión es obra del Espíritu que cruza barreras, forma comunidades generosas y aprende a discernir sin borrar identidades.','El Espíritu no elimina conflictos; permite atravesarlos mediante testimonio, escucha y decisión comunitaria. La misión avanza también por personas desplazadas y no solo por líderes reconocidos.','Hechos no ofrece una historia completa de todo el cristianismo primitivo ni un patrón único para cada detalle eclesial. Las tensiones con sinagogas no autorizan antisemitismo. Los relatos de juicio repentino no deben usarse para aterrorizar o atribuir muertes actuales a castigo.',ARRAY['Espíritu Santo','testimonio','Jerusalén','Samaria','gentiles','Pablo','Roma']::text[],ARRAY['judíos','samaritanos','gentiles','discípulos','romanos']::text[],ARRAY['Jerusalén','Samaria','Antioquía','Asia Menor','Grecia','Roma']::text[]),
('hechos-1-7-jerusalen','ACT','section',1,7,'Pentecostés y comunidad en Jerusalén','La ascensión, Pentecostés, vida compartida, sanidades, oposición y elección de servidores muestran el crecimiento de una comunidad que culmina con el testimonio de Esteban.','Jerusalén reunía peregrinos de la diáspora y funcionaba bajo autoridad sacerdotal y romana. El griego y el arameo coexistían en la comunidad.','Pentecostés corresponde a Shavuot. El discurso de Pedro interpreta Joel y Salmos; la vida compartida se relaciona con prácticas de cuidado y no elimina automáticamente toda propiedad.','Resúmenes idealizados alternan con conflictos internos y externos. La historia de Esteban revisa Israel y desplaza la misión más allá de Jerusalén.','Presentar al Espíritu formando una comunidad de testimonio, oración, generosidad y servicio que debe corregir desigualdades internas.','La espiritualidad comunitaria se verifica en distribución y atención a grupos ignorados. Los dones no sustituyen organización justa.','«Tenían todo en común» no puede imponerse coercitivamente. Ananías y Safira no deben usarse para amenazar a donantes. El discurso de Esteban es una disputa intrajudía y no condena al pueblo judío entero.',ARRAY['Pentecostés','Shavuot','comunidad','Esteban','servicio','generosidad']::text[],ARRAY['judíos de Judea','diáspora','helenistas','hebreos','autoridades']::text[],ARRAY['Jerusalén','templo']::text[]),
('hechos-8-12-fronteras','ACT','section',8,12,'Samaria, el funcionario etíope y la casa de Cornelio','La persecución dispersa a la comunidad, Felipe anuncia en Samaria y acompaña a un funcionario etíope, Saulo es llamado y Pedro aprende mediante una visión a recibir a Cornelio sin tratarlo como impuro.','Samaria, Gaza, Cesarea y Damasco conectaban poblaciones diversas. Funcionarios, eunucos, soldados y diáspora circulaban por rutas imperiales.','Isaías 56 ofrece trasfondo para la inclusión del eunuco. La visión de Pedro se refiere explícitamente a no llamar impura a ninguna persona y no solo a una discusión dietaria.','Historias de cruce de fronteras se alternan con la transformación de Saulo y una intervención divina frente a Herodes.','Mostrar que el Espíritu precede a la institución y obliga a revisar barreras religiosas cuando producen exclusión de personas que Dios recibe.','La conversión puede incluir desaprender prejuicios. Acompañar preguntas y escuchar experiencias son partes de la misión.','La historia de Saulo no justifica experiencias peligrosas ni desprecia procesos graduales. La visión de Pedro no debe usarse para decir que el judaísmo era impuro. La muerte de Herodes no permite interpretar enfermedades actuales como juicio.',ARRAY['Samaria','eunuco etíope','Saulo','Pedro','Cornelio','gentiles','inclusión']::text[],ARRAY['samaritanos','etíopes','judíos','gentiles','romanos']::text[],ARRAY['Samaria','Gaza','Damasco','Cesarea','Jope']::text[]),
('hechos-13-20-mision','ACT','section',13,20,'Antioquía, misiones y discernimiento comunitario','Desde Antioquía, Pablo y colaboradores viajan por Asia Menor y Grecia; el concilio de Jerusalén aborda la incorporación gentil y nuevas comunidades surgen entre sinagogas, hogares y espacios públicos.','Las ciudades romanas estaban conectadas por caminos, puertos, ciudadanía y redes comerciales. Las sinagogas de diáspora ofrecían puntos iniciales de contacto.','Hechos 15 preserva un debate judío sobre cómo gentiles participan en el pueblo mesiánico. La decisión no declara mala la circuncisión judía, sino que no la impone a gentiles como requisito de salvación.','Viajes, discursos adaptados a audiencias, conflictos y cartas forman una expansión que incluye desacuerdos entre líderes y equipos diversos.','Mostrar que la misión contextualiza sin manipular, que la diversidad requiere acuerdos y que ninguna cultura posee el evangelio como propiedad exclusiva.','El discernimiento maduro escucha testimonios, Escrituras y efectos concretos. Un desacuerdo entre colaboradores no necesariamente termina toda vocación.','Los conflictos con algunas sinagogas no describen a todos los judíos. El discurso de Atenas no autoriza desprecio por filosofía. Los disturbios no prueban automáticamente éxito espiritual y la misión no debe reproducir colonialismo.',ARRAY['Antioquía','Pablo','Bernabé','concilio','gentiles','Atenas','Éfeso']::text[],ARRAY['judíos de diáspora','gentiles','mujeres líderes','artesanos','romanos']::text[],ARRAY['Antioquía','Jerusalén','Asia Menor','Filipos','Atenas','Corinto','Éfeso']::text[]),
('hechos-21-28-roma','ACT','section',21,28,'Arresto, defensas y camino a Roma','Pablo regresa a Jerusalén, es arrestado, presenta defensas ante autoridades, apela al César, sobrevive a un naufragio y llega a Roma, donde el libro termina con el anuncio abierto del reino.','Ciudadanía romana, procesos judiciales, gobernadores, navegación mediterránea y patronazgo explican la ruta desde Jerusalén hasta Roma.','Pablo continúa identificándose como judío y participa en prácticas del templo. Sus defensas reinterpretan su misión gentil como fidelidad a la esperanza de Israel.','Una larga sección judicial reemplaza viajes misioneros libres por un viaje como prisionero. El final abierto muestra la palabra sin cadenas aunque Pablo esté limitado.','Enseñar que el testimonio puede continuar dentro de restricciones y que recursos legales pueden utilizarse sin convertir el imperio en salvador.','Una vocación no depende de controlar circunstancias. La hospitalidad de personas desconocidas y la calma en crisis sostienen el camino.','El naufragio no autoriza asumir riesgos marítimos imprudentes. Las palabras finales sobre algunos judíos no significan rechazo total de Israel. Hechos no narra el destino final de Pablo y no debe inventarse dentro del texto.',ARRAY['Jerusalén','arresto','ciudadanía romana','César','naufragio','Roma','reino']::text[],ARRAY['Pablo','judíos','romanos','marineros','habitantes de Malta']::text[],ARRAY['Jerusalén','Cesarea','Malta','Roma']::text[])
)
insert into public.biblical_context_units(slug,book_code,source_id,scope_kind,chapter_start,verse_start,chapter_end,verse_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places,source_locator,provider_version,content_hash,review_status,enabled,metadata)
select data.slug,data.book_code,source.id,data.scope_kind,data.chapter_start,NULL,data.chapter_end,NULL,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions,data.key_terms,data.people_groups,data.places,'vida://corpus/contexto/evangelios-hechos/v1#'||data.slug,'evangelios-hechos-v1-2026-08-02',encode(extensions.digest(concat_ws('|',data.slug,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions),'sha256'),'hex'),'approved',true,jsonb_build_object('coverage_batch','gospels-acts','generated_by_ai',false,'review_level','editorial') from data cross join source
on conflict(slug) do update set book_code=excluded.book_code,source_id=excluded.source_id,scope_kind=excluded.scope_kind,chapter_start=excluded.chapter_start,chapter_end=excluded.chapter_end,title=excluded.title,summary=excluded.summary,historical_context=excluded.historical_context,jewish_context=excluded.jewish_context,literary_context=excluded.literary_context,authorial_intent=excluded.authorial_intent,theological_reflection=excluded.theological_reflection,interpretive_cautions=excluded.interpretive_cautions,key_terms=excluded.key_terms,people_groups=excluded.people_groups,places=excluded.places,source_locator=excluded.source_locator,provider_version=excluded.provider_version,content_hash=excluded.content_hash,review_status='approved',enabled=true,metadata=excluded.metadata,updated_at=now();